PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?lossReserveAmount
WHERE {
  SERVICE <mapped> {
    ?policy a ins:Policy ;
            ins:policyNumber ?policyNumber ;
            ins:soldByAgent ?agent .

    ?agent a ins:Agent ;
           ins:agentId ?agentId .

    ?coverage a ins:PolicyCoverageDetail ;
              ins:hasPolicy ?policy .

    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber ;
           ins:against ?coverage ;
           ins:hasLossReserve ?lossReserve .

    ?lossReserve a ins:LossReserve ;
                 ins:lossReserveAmount ?lossReserveAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber ?lossReserveAmount

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?agentId
WHERE {
  SERVICE <mapped> {
    ?policy a ins:Policy ;
            ins:policyNumber ?policyNumber ;
            ins:soldByAgent ?agent .
    ?agent a ins:Agent ;
           ins:agentId ?agentId .
  }
}

PREFIX ins: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?policyNumber (AVG(?daysToSettle) AS ?avgTimeToSettleDays)
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimOpenDate ?openDate ;
           ins:claimCloseDate ?closeDate ;
           ins:against ?pcd .

    ?pcd ins:hasPolicy ?policy .
    ?policy ins:policyNumber ?policyNumber .

    BIND((xsd:dateTime(?closeDate) - xsd:dateTime(?openDate)) / "P1D"^^xsd:dayTimeDuration AS ?daysToSettle)
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?policyNumber
       (COALESCE(SUM(?lossPaymentAmount), 0) +
        COALESCE(SUM(?lossReserveAmount), 0) +
        COALESCE(SUM(?expensePaymentAmount), 0) +
        COALESCE(SUM(?expenseReserveAmount), 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim ins:against ?pcd .

    ?pcd ins:hasPolicy ?policy .
    ?policy ins:policyNumber ?policyNumber .

    OPTIONAL {
      ?claim ins:hasLossPayment ?lp .
      ?lp ins:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasLossReserve ?lr .
      ?lr ins:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpensePayment ?ep .
      ?ep ins:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpenseReserve ?er .
      ?er ins:expenseReserveAmount ?expenseReserveAmount .
    }
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber ;
           ins:hasExpenseReserve ?expenseReserve .
    ?expenseReserve ins:expenseReserveAmount ?expenseReserveAmount .
  }
}
